/**
 * @description Reading one Integration Connection or Integration Event for the guided setup: which object it is,
 * whether the user may see it (USER_MODE, as View request does for a transaction), its values, lookup names and the
 * summary facts (the connection's Named Credential, the inbound user's permission set, the events on a connection).
 * @group Integration Hub
 */
public with sharing class IntegrationHubSetupRecord {

    private static final Integer EVENT_ROWS = 5;

    /**
     * @description The object of the setup, checked: only IH_Event__c and IH_Connection__c.
     * @param objectApiName the object named by the screen (may be blank when recordId is given)
     * @param recordId the record, or null
     * @return IH_Event__c or IH_Connection__c
     */
    public static String objectOf(String objectApiName, Id recordId) {
        String name = recordId == null ? objectApiName : String.valueOf(recordId.getSObjectType());
        if (recordId != null && String.isNotBlank(objectApiName) && !objectApiName.equalsIgnoreCase(name)) {
            throw IntegrationHubPreview.auraError('The record is not a ' + objectApiName + '.');
        }
        for (String known : new List<String>{ IntegrationHubSetup.EVENT_OBJECT, IntegrationHubSetup.CONNECTION_OBJECT }) {
            if (known.equalsIgnoreCase(name)) {
                return known;
            }
        }
        throw IntegrationHubPreview.auraError('Only Integration Connections and Integration Events are set up here.');
    }

    /**
     * @description Refuses a record the user cannot see with their own access.
     * @param objectName IH_Event__c or IH_Connection__c
     * @param recordId the record
     */
    public static void requireVisible(String objectName, Id recordId) {
        Integer visible;
        try {
            visible = objectName == IntegrationHubSetup.EVENT_OBJECT
                ? [SELECT COUNT() FROM IH_Event__c WHERE Id = :recordId WITH USER_MODE]
                : [SELECT COUNT() FROM IH_Connection__c WHERE Id = :recordId WITH USER_MODE];
        } catch (QueryException e) {
            visible = 0;
        }
        if (visible == 0) {
            throw IntegrationHubPreview.auraError('You cannot open this record.');
        }
    }

    /**
     * @description Fills the values, lookup names and summary facts of a record the user can see.
     * @param s the setup (objectApiName and recordId set)
     */
    public static void fill(IntegrationHubSetup.Setup s) {
        Boolean isEvent = s.objectApiName == IntegrationHubSetup.EVENT_OBJECT;
        List<String> editable = IntegrationHubSetupSchema.editableFields(s.objectApiName);
        List<String> fields = new List<String>(editable);
        fields.addAll(isEvent ? new List<String>{ 'Connection__r.Name', 'Connection__r.Named_Credential__c' }
            : new List<String>{ 'Inbound_User__r.Name' });
        SObject rec = IntegrationHubData.queryFirst('SELECT Id, ' + String.join(fields, ', ') + ' FROM ' + s.objectApiName
            + ' WHERE Id = :id LIMIT 1', new Map<String, Object>{ 'id' => s.recordId });
        if (rec == null) {
            throw IntegrationHubPreview.auraError('Record not found.');
        }
        for (String api : editable) {
            s.values.put(api, rec.get(api));
        }
        if (isEvent) {
            eventFacts(s, rec.getSObject('Connection__r'));
            s.relatedObject = objectSummary((String) rec.get('Related_Object__c'));
        } else {
            connectionFacts(s, rec);
        }
    }

    /**
     * @description Label, API name and Id key prefix of an object, for the Related Object of an event.
     * @param objectName the API name (may be blank)
     * @return value = API name, label = object label, detail = "API name Voucher__c · Id prefix a0X"; null when blank
     * or unknown
     */
    public static IntegrationHubSetup.Option objectSummary(String objectName) {
        Schema.DescribeSObjectResult d = IntegrationHubSetupSchema.describeOrNull(objectName);
        if (d == null) {
            return null;
        }
        return new IntegrationHubSetup.Option(d.getName(), d.getLabel(), objectDetail(d.getName(), d.getKeyPrefix()));
    }

    /**
     * @description The detail line of an object: API name and, when the object has one, its Id key prefix.
     * @param api the API name
     * @param keyPrefix the Id key prefix (may be blank)
     * @return e.g. "API name Voucher__c · Id prefix a0X"
     */
    public static String objectDetail(String api, String keyPrefix) {
        return 'API name ' + api + (String.isBlank(keyPrefix) ? '' : ' · Id prefix ' + keyPrefix);
    }

    private static void eventFacts(IntegrationHubSetup.Setup s, SObject conn) {
        s.names.put('Connection__c', conn == null ? null : (String) conn.get('Name'));
        s.credential = conn == null ? null : (String) conn.get('Named_Credential__c');
        s.credentialExists = IntegrationHubSetupOptions.credentialExists(s.credential);
    }

    private static void connectionFacts(IntegrationHubSetup.Setup s, SObject rec) {
        SObject inboundUser = rec.getSObject('Inbound_User__r');
        s.names.put('Inbound_User__c', inboundUser == null ? null : (String) inboundUser.get('Name'));
        s.credentialExists = IntegrationHubSetupOptions.credentialExists((String) rec.get('Named_Credential__c'));
        s.userAccess = IntegrationHubSetupOptions.userAccess((Id) rec.get('Inbound_User__c'));
        for (SObject row : IntegrationHubData.query('SELECT Id, Event_Key__c, Direction__c, Active__c FROM IH_Event__c '
                + 'WHERE Connection__c = :id ORDER BY Event_Key__c LIMIT 2000', new Map<String, Object>{ 'id' => s.recordId })) {
            addEvent(s, (IH_Event__c) row);
        }
    }

    private static void addEvent(IntegrationHubSetup.Setup s, IH_Event__c ev) {
        s.eventCount++;
        if (ev.Direction__c == IntegrationHub.INBOUND) {
            s.inboundCount++;
        }
        if (s.events.size() < EVENT_ROWS) {
            IntegrationHubSetup.EventRow r = new IntegrationHubSetup.EventRow();
            r.id = ev.Id;
            r.eventKey = ev.Event_Key__c;
            r.direction = ev.Direction__c;
            r.active = ev.Active__c;
            s.events.add(r);
        }
    }
}
